#include <stdio.h>

int main()
{
    int n = 41;
    int schritte = 200;
    double r = 0.4;
    double u[41];
    double w[41];
    double summe = 0.0;
    int i, s;

    for (i = 0; i < n; i++) u[i] = 0.0;
    u[n / 2] = 1.0;

    for (s = 0; s < schritte; s++) {
        for (i = 1; i < n - 1; i++)
            w[i] = u[i] + r * (u[i-1] - 2 * u[i] + u[i+1]);
        w[0] = u[0] + r * (u[1] - u[0]);
        w[n-1] = u[n-1] + r * (u[n-2] - u[n-1]);
        for (i = 0; i < n; i++) u[i] = w[i];
    }

    for (i = 0; i < n; i++) summe += u[i];
    printf("%.6f %.6f\n", u[n/2], summe);
    return 0;
}

