#include <stdio.h>

int main()
{
    int n = 16;
    double ux[16][16];
    double uy[16][16];
    double d[16][16];
    double p[16][16];
    double q[16][16];
    double vorher = 0.0;
    double nachher = 0.0;
    double w;
    int i, j, it;

    for (j = 0; j < n; j++)
        for (i = 0; i < n; i++) {
            ux[j][i] = (i - n / 2.0) / n;
            uy[j][i] = (j - n / 2.0) / n;
            p[j][i] = 0.0;
            d[j][i] = 0.0;
        }

    for (j = 1; j < n - 1; j++)
        for (i = 1; i < n - 1; i++) {
            d[j][i] = 0.5 * (ux[j][i+1] - ux[j][i-1])
                    + 0.5 * (uy[j+1][i] - uy[j-1][i]);
            w = d[j][i];
            if (w < 0) w = -w;
            if (w > vorher) vorher = w;
        }

    for (it = 0; it < 200; it++) {
        for (j = 1; j < n - 1; j++)
            for (i = 1; i < n - 1; i++)
                q[j][i] = 0.25 * (p[j][i+1] + p[j][i-1]
                                + p[j+1][i] + p[j-1][i] - d[j][i]);
        for (j = 1; j < n - 1; j++)
            for (i = 1; i < n - 1; i++)
                p[j][i] = q[j][i];
    }

    for (j = 1; j < n - 1; j++)
        for (i = 1; i < n - 1; i++) {
            ux[j][i] -= 0.5 * (p[j][i+1] - p[j][i-1]);
            uy[j][i] -= 0.5 * (p[j+1][i] - p[j-1][i]);
        }

    for (j = 2; j < n - 2; j++)
        for (i = 2; i < n - 2; i++) {
            w = 0.5 * (ux[j][i+1] - ux[j][i-1])
              + 0.5 * (uy[j+1][i] - uy[j-1][i]);
            if (w < 0) w = -w;
            if (w > nachher) nachher = w;
        }

    printf("Divergenz vorher %.6f nachher %.6f\n", vorher, nachher);
    return 0;
}

